"use strict";
import { useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { useReadContract } from "wagmi";
import { getContractAddress, getContractAbi, ABSTRACT_TESTNET_CHAIN_ID } from "uniswap/src/constants/contracts";
import { useVoterReads } from "./useVoterContract";
import { formatEther } from "viem";
const GAUGES_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/abx-gauges/api";
async function fetchGaugeIncentives() {
  try {
    const response = await fetch(GAUGES_SUBGRAPH_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        query: `
          query GetGaugesWithIncentives {
            gauges(first: 100, where: { isAlive: true }) {
              id
              pool
              poolType
              totalWeight
              emissions
              rewardDistributions(first: 10, orderBy: timestamp, orderDirection: desc) {
                amount
                token
                timestamp
                epoch
              }
              bribeContract
              feeContract
            }
          }
        `
      })
    });
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }
    const data = await response.json();
    if (data.errors) {
      console.error("GraphQL errors:", data.errors);
      throw new Error(`GraphQL errors: ${JSON.stringify(data.errors)}`);
    }
    const gauges = data.data?.gauges || [];
    let totalIncentives = 0;
    let totalEmissions = 0;
    gauges.forEach((gauge) => {
      if (gauge.emissions && gauge.emissions !== "0") {
        const emissions = parseFloat(formatEther(BigInt(gauge.emissions)));
        totalEmissions += emissions;
      }
      gauge.rewardDistributions.forEach((distribution) => {
        if (distribution.amount && distribution.amount !== "0") {
          const amount = parseFloat(formatEther(BigInt(distribution.amount)));
          totalIncentives += amount;
        }
      });
    });
    return { totalIncentives, totalEmissions };
  } catch (error) {
    console.error("Failed to fetch gauge incentives:", error);
    return { totalIncentives: 0, totalEmissions: 0 };
  }
}
export function useVotingRoundData() {
  const {
    epochStart,
    epochNext,
    epochVoteStart,
    epochVoteEnd
  } = useVoterReads();
  const votingEscrowAddress = getContractAddress(ABSTRACT_TESTNET_CHAIN_ID, "VotingEscrow");
  const votingEscrowAbi = getContractAbi(ABSTRACT_TESTNET_CHAIN_ID, "VotingEscrow");
  const minterAddress = getContractAddress(ABSTRACT_TESTNET_CHAIN_ID, "Minter");
  const minterAbi = getContractAbi(ABSTRACT_TESTNET_CHAIN_ID, "Minter");
  const { data: totalSupply, isLoading: isLoadingSupply } = useReadContract({
    address: votingEscrowAddress,
    abi: votingEscrowAbi,
    functionName: "totalSupply",
    query: {
      enabled: !!votingEscrowAddress && !!votingEscrowAbi,
      refetchInterval: 6e4,
      // Refetch every minute
      staleTime: 3e4
      // Consider stale after 30 seconds
    }
  });
  const { data: weeklyEmissions, isLoading: isLoadingEmissions } = useReadContract({
    address: minterAddress,
    abi: minterAbi,
    functionName: "weekly",
    query: {
      enabled: !!minterAddress && !!minterAbi,
      refetchInterval: 3e5,
      // Refetch every 5 minutes (less frequent)
      staleTime: 6e4
      // Consider stale after 1 minute
    }
  });
  const { data: gaugeData, isLoading: isLoadingGauges } = useQuery({
    queryKey: ["gauge-incentives"],
    queryFn: fetchGaugeIncentives,
    refetchInterval: 6e4,
    // Refetch every minute
    staleTime: 3e4
    // Consider stale after 30 seconds
  });
  const timingData = useMemo(() => {
    const currentTime = Date.now() / 1e3;
    const currentRound = epochStart ? Math.floor((currentTime - epochStart) / (7 * 24 * 60 * 60)) + 1 : 1;
    let daysRemaining = 0;
    let hoursRemaining = 0;
    let isVotingPeriod = false;
    if (epochNext) {
      const timeUntilNext = epochNext - currentTime;
      if (timeUntilNext > 0) {
        daysRemaining = Math.floor(timeUntilNext / (24 * 60 * 60));
        hoursRemaining = Math.floor(timeUntilNext % (24 * 60 * 60) / (60 * 60));
      }
    }
    if (epochVoteStart && epochVoteEnd) {
      isVotingPeriod = currentTime >= epochVoteStart && currentTime <= epochVoteEnd;
    }
    return {
      currentRound,
      daysRemaining,
      hoursRemaining,
      isVotingPeriod
    };
  }, [epochStart, epochNext, epochVoteStart, epochVoteEnd]);
  const financialData = useMemo(() => {
    const totalIncentives = gaugeData?.totalIncentives || 0;
    const totalEmissions = gaugeData?.totalEmissions || 0;
    const totalFees = 2809680;
    const totalRewards = totalIncentives + totalEmissions;
    return {
      totalFees: totalFees.toString(),
      totalIncentives: totalIncentives.toString(),
      // Real ABX incentive amounts
      totalRewards: totalRewards.toString()
      // Real total rewards
    };
  }, [gaugeData]);
  const votingPowerData = useMemo(() => {
    const totalVotingPower = totalSupply ? totalSupply.toString() : "0";
    const totalVotingPowerFormatted = totalSupply ? formatEther(totalSupply) : "0";
    return {
      totalVotingPower,
      totalVotingPowerFormatted
    };
  }, [totalSupply]);
  const emissionsData = useMemo(() => {
    const newEmissions = weeklyEmissions ? formatEther(weeklyEmissions) : "0";
    return { newEmissions };
  }, [weeklyEmissions]);
  const isLoading = isLoadingSupply || isLoadingEmissions || isLoadingGauges;
  return {
    // Timing data
    ...timingData,
    // Voting power data
    ...votingPowerData,
    // Financial data (now using real gauge data!)
    ...financialData,
    ...emissionsData,
    // Loading states
    isLoading
  };
}
export const VotingRoundUtils = {
  /**
   * Format large numbers for display (e.g., 858.94M)
   */
  formatLargeNumber: (value) => {
    const num = parseFloat(value);
    if (num >= 1e9) {
      return `${(num / 1e9).toFixed(2)}B`;
    } else if (num >= 1e6) {
      return `${(num / 1e6).toFixed(2)}M`;
    } else if (num >= 1e3) {
      return `${(num / 1e3).toFixed(2)}K`;
    }
    return num.toFixed(2);
  },
  /**
   * Format USD values for display
   */
  formatUSDValue: (value) => {
    const num = parseFloat(value);
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(num);
  },
  /**
   * Get time remaining display text
   */
  getTimeRemainingText: (days, hours) => {
    if (days > 0) {
      return `ends in ${days} ${days === 1 ? "day" : "days"}`;
    } else if (hours > 0) {
      return `ends in ${hours} ${hours === 1 ? "hour" : "hours"}`;
    }
    return "ending soon";
  },
  /**
   * Get voting period status text
   */
  getVotingPeriodText: (isVotingPeriod) => {
    return isVotingPeriod ? "Voting is open" : "Voting closed";
  }
};
